import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import DashboardLayout from '../components/DashboardLayout';
import { useAuth } from '../App';

const PRODUCTIVITY = { score: 82, profit: 42000, soilHealth: 74, waterEff: 68, marketTrend: '+12%' };
const RISKS = [
  { label: 'Climate Risk', level: 'Medium', score: 52, color: 'risk-medium' },
  { label: 'Market Risk', level: 'Low', score: 22, color: 'risk-low' },
  { label: 'Disease Risk', level: 'Low', score: 18, color: 'risk-low' },
  { label: 'Drought Risk', level: 'Medium', score: 45, color: 'risk-medium' },
];
const AI_SUMMARY = [
  { icon: '🌾', text: 'Sow Wheat by Nov 20 for optimal yield', priority: 'High' },
  { icon: '💧', text: 'Irrigate on Tuesday — soil moisture at 42%', priority: 'Medium' },
  { icon: '🧪', text: 'Apply 25kg Urea/acre before next rain', priority: 'High' },
  { icon: '📈', text: 'Hold wheat — prices rising next 2 weeks', priority: 'Info' },
  { icon: '🔬', text: 'Monitor for rust — humidity elevated', priority: 'Medium' },
];

function ScoreRing({ score, size = 80, color = '#22c55e', label }) {
  const r = (size - 12) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ - (score / 100) * circ;
  return (
    <div className="flex flex-col items-center gap-1">
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="6" />
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth="6"
          strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round" className="progress-ring" />
      </svg>
      <div className="text-center -mt-1">
        <div className="font-display font-bold text-white text-lg leading-none">{score}</div>
        {label && <div className="text-gray-500 text-xs">{label}</div>}
      </div>
    </div>
  );
}

function MiniChart({ data, color = '#22c55e' }) {
  const canvasRef = useRef();
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !window.Chart) return;
    const existing = window.Chart.getChart(canvas);
    if (existing) existing.destroy();
    new window.Chart(canvas, {
      type: 'line',
      data: {
        labels: data.map((_, i) => i),
        datasets: [{ data, borderColor: color, borderWidth: 2, fill: true,
          backgroundColor: color + '20', tension: 0.4, pointRadius: 0 }]
      },
      options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } },
        scales: { x: { display: false }, y: { display: false } }, animation: { duration: 1000 } }
    });
  }, [data, color]);
  return <div className="h-12"><canvas ref={canvasRef} /></div>;
}

function RiskMeter({ level, score, color, label }) {
  const colors = { 'risk-low': '#22c55e', 'risk-medium': '#f59e0b', 'risk-high': '#ef4444' };
  const textColors = { 'risk-low': 'text-green-400', 'risk-medium': 'text-yellow-400', 'risk-high': 'text-red-400' };
  return (
    <div className="glass-dark rounded-xl p-3">
      <div className="flex justify-between items-center mb-2">
        <span className="text-gray-400 text-xs">{label}</span>
        <span className={`text-xs font-bold ${textColors[color]}`}>{level}</span>
      </div>
      <div className="h-1.5 bg-black/40 rounded-full overflow-hidden">
        <div className={`h-full rounded-full transition-all duration-1000 ${color}`} style={{ width: `${score}%` }} />
      </div>
    </div>
  );
}

export default function Dashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [time, setTime] = useState(new Date());
  const profitData = [28, 32, 29, 35, 38, 34, 42, 40, 45, 42, 48, 52];
  const weatherData = [22, 25, 28, 26, 24, 27, 30, 28, 26, 29, 31, 28];

  useEffect(() => { const t = setInterval(() => setTime(new Date()), 60000); return () => clearInterval(t); }, []);
  const hour = time.getHours();
  const greeting = hour < 12 ? 'Good Morning' : hour < 17 ? 'Good Afternoon' : 'Good Evening';

  const priorityColors = { High: 'text-red-400 bg-red-900/20 border-red-800/30', Medium: 'text-yellow-400 bg-yellow-900/20 border-yellow-800/30', Info: 'text-blue-400 bg-blue-900/20 border-blue-800/30' };

  return (
    <DashboardLayout title="Productivity Dashboard" subtitle={time.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}>

      {/* Greeting Banner */}
      <div className="glass rounded-2xl p-5 mb-5 border border-green-900/30 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
        <div>
          <h2 className="font-display font-bold text-xl text-white">{greeting}, {user?.name || 'Farmer'} 👋</h2>
          <p className="text-gray-400 text-sm mt-0.5">AI has <span className="text-green-400 font-semibold">5 new recommendations</span> for your farm today.</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          {user?.gps && <div className="glass-green px-3 py-1.5 rounded-xl text-green-300 text-xs border border-green-700/30">📍 GPS Active</div>}
          <div className="glass px-3 py-1.5 rounded-xl text-gray-300 text-xs">{user?.crop || 'Wheat'} · {user?.acres || '5'} Acres</div>
          <div className="glass px-3 py-1.5 rounded-xl text-gray-300 text-xs">{user?.state || 'Maharashtra'}</div>
        </div>
      </div>

      {/* Productivity Score Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-5">
        {[
          { label: 'Productivity Score', score: PRODUCTIVITY.score, color: '#22c55e', sub: 'Overall' },
          { label: 'Soil Health', score: PRODUCTIVITY.soilHealth, color: '#f59e0b', sub: 'Index' },
          { label: 'Water Efficiency', score: PRODUCTIVITY.waterEff, color: '#38bdf8', sub: 'Score' },
          { label: 'Sustainability', score: 71, color: '#a78bfa', sub: 'Rating' },
        ].map(item => (
          <div key={item.label} className="glass rounded-2xl p-4 border border-green-900/30 flex flex-col items-center card-hover">
            <ScoreRing score={item.score} color={item.color} label={item.sub} />
            <div className="text-gray-400 text-xs text-center mt-2">{item.label}</div>
          </div>
        ))}
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-5 mb-5">

        {/* Profit Analytics */}
        <div className="glass rounded-2xl p-5 border border-green-900/30">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2"><span>💰</span><h3 className="font-semibold text-white text-sm">Profit Analytics</h3></div>
            <span className="text-green-400 text-xs font-bold">{PRODUCTIVITY.marketTrend}</span>
          </div>
          <div className="font-display font-black text-3xl gradient-text-gold mb-1">₹{PRODUCTIVITY.profit.toLocaleString()}</div>
          <div className="text-gray-500 text-xs mb-3">Estimated this season</div>
          <MiniChart data={profitData} color="#22c55e" />
          <div className="grid grid-cols-2 gap-2 mt-3">
            <div className="glass-dark rounded-xl p-2 text-center">
              <div className="text-green-400 font-bold text-sm">₹8,400</div>
              <div className="text-gray-600 text-xs">Per Acre</div>
            </div>
            <div className="glass-dark rounded-xl p-2 text-center">
              <div className="text-blue-400 font-bold text-sm">₹2,150</div>
              <div className="text-gray-600 text-xs">Market Price/Q</div>
            </div>
          </div>
        </div>

        {/* Weather Forecast */}
        <div className="glass rounded-2xl p-5 border border-green-900/30 cursor-pointer card-hover" onClick={() => navigate('/weather')}>
          <div className="flex items-center gap-2 mb-3"><span>🌤</span><h3 className="font-semibold text-white text-sm">Weather Forecast</h3></div>
          <div className="flex items-center gap-3 mb-3">
            <span className="text-4xl">⛅</span>
            <div>
              <div className="font-display font-bold text-3xl text-white">28°C</div>
              <div className="text-gray-400 text-xs">Partly Cloudy · Feels 26°C</div>
            </div>
          </div>
          <MiniChart data={weatherData} color="#38bdf8" />
          <div className="grid grid-cols-3 gap-2 mt-3">
            {[{ l: 'Humidity', v: '65%' }, { l: 'Rain', v: '12mm' }, { l: 'Wind', v: '14km/h' }].map(i => (
              <div key={i.l} className="glass-dark rounded-xl p-2 text-center">
                <div className="text-blue-400 font-bold text-xs">{i.v}</div>
                <div className="text-gray-600 text-xs">{i.l}</div>
              </div>
            ))}
          </div>
          <div className="mt-3 glass-green rounded-xl p-2 text-center">
            <span className="text-yellow-400 text-xs font-semibold">⚠️ Heavy rain alert Thursday</span>
          </div>
        </div>

        {/* AI Risk System */}
        <div className="glass rounded-2xl p-5 border border-green-900/30">
          <div className="flex items-center gap-2 mb-4"><span>🛡️</span><h3 className="font-semibold text-white text-sm">AI Risk Reduction</h3></div>
          <div className="space-y-3">
            {RISKS.map(r => <RiskMeter key={r.label} {...r} />)}
          </div>
          <button onClick={() => navigate('/recommendations')} className="w-full mt-4 glass-green border border-green-700/30 text-green-300 text-xs font-semibold py-2 rounded-xl hover:bg-green-900/30 transition-all">
            View Full Risk Analysis →
          </button>
        </div>
      </div>

      {/* Bottom Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">

        {/* AI Recommendation Summary */}
        <div className="glass rounded-2xl p-5 border border-green-900/30">
          <div className="flex items-center gap-2 mb-4">
            <div className="w-7 h-7 rounded-lg btn-primary flex items-center justify-center text-sm ai-glow">🤖</div>
            <h3 className="font-semibold text-white text-sm">AI Recommendation Summary</h3>
          </div>
          <div className="space-y-2">
            {AI_SUMMARY.map((item, i) => (
              <div key={i} className="flex items-start gap-3 p-2.5 rounded-xl hover:bg-white/5 transition-all">
                <span className="text-lg flex-shrink-0">{item.icon}</span>
                <div className="flex-1 min-w-0">
                  <div className="text-gray-200 text-xs leading-relaxed">{item.text}</div>
                </div>
                <span className={`text-xs px-2 py-0.5 rounded-full border flex-shrink-0 ${priorityColors[item.priority]}`}>{item.priority}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Quick Actions Grid */}
        <div className="glass rounded-2xl p-5 border border-green-900/30">
          <h3 className="font-semibold text-white text-sm mb-4">Quick Actions</h3>
          <div className="grid grid-cols-3 gap-3">
            {[
              { icon: '🌱', label: 'Crop AI', path: '/recommendations', color: 'from-green-900/40 to-green-950/40 border-green-800/30' },
              { icon: '📈', label: 'Market', path: '/market', color: 'from-blue-900/40 to-blue-950/40 border-blue-800/30' },
              { icon: '🔬', label: 'Disease', path: '/disease-scanner', color: 'from-red-900/40 to-red-950/40 border-red-800/30' },
              { icon: '💧', label: 'Water', path: '/water', color: 'from-cyan-900/40 to-cyan-950/40 border-cyan-800/30' },
              { icon: '🧪', label: 'Fertilizer', path: '/fertilizer', color: 'from-yellow-900/40 to-yellow-950/40 border-yellow-800/30' },
              { icon: '♻️', label: 'Eco Farm', path: '/sustainability', color: 'from-purple-900/40 to-purple-950/40 border-purple-800/30' },
              { icon: '🌤', label: 'Weather', path: '/weather', color: 'from-sky-900/40 to-sky-950/40 border-sky-800/30' },
              { icon: '🧠', label: 'AI Agents', path: '/agents', color: 'from-indigo-900/40 to-indigo-950/40 border-indigo-800/30' },
              { icon: '🤖', label: 'KisanGPT', path: '/chatbot', color: 'from-violet-900/40 to-violet-950/40 border-violet-800/30' },
            ].map(a => (
              <button key={a.path} onClick={() => navigate(a.path)}
                className={`bg-gradient-to-br ${a.color} border rounded-xl p-3 text-center card-hover backdrop-blur-sm`}>
                <div className="text-2xl mb-1">{a.icon}</div>
                <div className="text-white text-xs font-medium">{a.label}</div>
              </button>
            ))}
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}
